import{_ as o,a0 as a,w as i,s as l,ao as r,I as e,a1 as u,A as s,x as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"如何在 Ubuntu 上設置多語言輸入法 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 上設置多語言輸入法 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 上設置多語言輸入法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 上設置多語言輸入法 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190815 How To Setup Multilingual Input Method On Ubuntu","title":"如何在 Ubuntu 上設置多語言輸入法","tag":"201908","desc":""},"relativePath":"201908/20190815 How To Setup Multilingual Input Method On Ubuntu.md","filePath":"[post].md"}'),g={name:"201908/20190815 How To Setup Multilingual Input Method On Ubuntu.md"};function m(b,t,d,h,w,c){const p=a("Link");return i(),l("div",null,[t[16]||(t[16]=r('<h1 id="如何在-ubuntu-上設置多語言輸入法" tabindex="-1">如何在 Ubuntu 上設置多語言輸入法 <a class="header-anchor" href="#如何在-ubuntu-上設置多語言輸入法" aria-label="Permalink to “如何在 Ubuntu 上設置多語言輸入法”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201908/21/231916g3gxbhybq0zv0q1h.jpg" alt=""></p><p>或許你不知道，在印度有數以百計的語言被使用，其中 22 種被印度機構列為官方語言。我的母語不是英語，因此當我需要從英語輸入或者翻譯到我的母語泰米爾語時我經常使用<strong>谷歌翻譯</strong>。嗯，我估計我不再需要依靠谷歌翻譯了。我剛發現在 Ubuntu 上輸入印度語的好辦法。這篇教程解釋瞭如何配置多語言輸入法的方法。這個是為 Ubuntu 18.04 LTS 特別打造的，但是它可以在其它類 Ubuntu 系統例如 Linux mint、Elementary OS 上使用。</p><h3 id="在-ubuntu-linux-上設置多語言輸入法" tabindex="-1">在 Ubuntu Linux 上設置多語言輸入法 <a class="header-anchor" href="#在-ubuntu-linux-上設置多語言輸入法" aria-label="Permalink to “在 Ubuntu Linux 上設置多語言輸入法”">​</a></h3><p>通過 <strong>IBus</strong> 的幫助，我們可以輕鬆在 Ubuntu 及其衍生物上配置多語言輸入法。Ibus，代表 <strong>I</strong> ntelligent <strong>I</strong> nput <strong>Bus</strong>（智能輸入總線），是一種針對類 Unix 操作系統下多語言輸入的輸入法框架。它使得我們可以在大多數 GUI 應用例如 LibreOffice 下輸入母語。</p><h3 id="在-ubuntu-上安裝-ibus" tabindex="-1">在 Ubuntu 上安裝 IBus <a class="header-anchor" href="#在-ubuntu-上安裝-ibus" aria-label="Permalink to “在 Ubuntu 上安裝 IBus”">​</a></h3><p>在 Ubuntu 上 安裝 IBus 包，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install ibus-m17n</span></span></code></pre></div><p>Ibus-m17n 包提供了許多印度語和其它國家語言包括阿姆哈拉語，阿拉伯語，阿美尼亞語，阿薩姆語，阿薩巴斯卡語，白俄羅斯語，孟加拉語，緬甸語，中高棉語，佔文，<strong>漢語</strong>，克里語，克羅地亞語，捷克語，丹麥語，迪維希語，馬爾代夫語，世界語，法語，格魯吉亞語，古/現代希臘語，古吉拉特語，希伯來語，因紐特語，日語，卡納達語，克什米爾語，哈薩克語，韓語，老撾語，馬來語，馬拉地語，尼泊爾語，歐吉布威語，歐瑞亞語，旁遮普語，波斯語，普什圖語，俄語，梵語，塞爾維亞語，四川彝文，彝文，西格西卡語，信德語，僧伽羅語，斯洛伐克語，瑞典語，泰語，泰米爾語，泰盧固語，藏語，維吾爾語，烏都語，烏茲別克語，越語及意第緒語。</p><h5 id="添加輸入語言" tabindex="-1">添加輸入語言 <a class="header-anchor" href="#添加輸入語言" aria-label="Permalink to “添加輸入語言”">​</a></h5><p>我們可以在系統裏的<strong>設置</strong>部分添加語言。點擊你的 Ubuntu 桌面右上角的下拉箭頭選擇底部左下角的設置圖標。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/Ubuntu-system-settings.png" alt=""></p><p><em>從頂部面板啓動系統設置</em></p><p>從設置部分，點擊左側面板的<strong>區域及語言</strong>選項。再點擊右側<strong>輸入來源</strong>標籤下的<strong>+</strong>（加號）按鈕。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Region-language-in-Settings-ubuntu.png" alt=""></p><p><em>設置部分的區域及語言選項</em></p><p>在下個窗口，點擊<strong>三個垂直的點</strong>按鈕。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Add-input-source-in-Ubuntu.png" alt=""></p><p><em>在 Ubuntu 裏添加輸入來源</em></p><p>搜尋並選擇你想從列表中添加的輸入語言。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Add-input-language.png" alt=""></p><p><em>添加輸入語言</em></p><p>在本篇教程中，我將加入<strong>泰米爾</strong>語。在選擇語言後，點擊<strong>添加</strong>按鈕。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Add-Input-Source-Ubuntu.png" alt=""></p><p><em>添加輸入來源</em></p><p>現在你會看到選中的輸入來源已經被添加了。你會在輸入來源標籤下的區域及語言選項中看到它。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Input-sources-Ubuntu.png" alt=""></p><p><em>Ubuntu 裏的輸入來源選項</em></p><p>點擊輸入來源標籤下的“管理安裝的語言”按鈕</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Manage-Installed-Languages.png" alt=""></p><p><em>在 Ubuntu 裏管理安裝的語言</em></p><p>接下來你會被詢問是否想要為選定語言安裝翻譯包。如果你想的話你可以安裝它們。或者僅僅選擇“稍後提醒我”按鈕。你下次打開的時候會收到統治。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/The-language-support-is-not-installed-completely.png" alt=""></p><p><em>語言支持沒完全安裝好</em></p><p>一旦翻譯包安裝好，點擊<strong>安裝/移除語言</strong>按鈕。同時確保 IBus 在鍵盤輸入法系統中被選中。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Install-Remove-languages.png" alt=""></p><p><em>在 Ubuntu 中安裝/移除語言</em></p><p>從列表中選擇你想要的語言並點擊採用按鈕。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Choose-language.png" alt=""></p><p><em>選擇輸入語言</em></p><p>到此為止了。我們已成功在 Ubuntu 18.04 桌面上配置好多語輸入方法。同樣的，你可以添加儘可能多的輸入語言。</p><p>在添加完所有語言來源後，登出再登陸回去。</p><h3 id="用印度語或者你喜歡的語言輸入" tabindex="-1">用印度語或者你喜歡的語言輸入 <a class="header-anchor" href="#用印度語或者你喜歡的語言輸入" aria-label="Permalink to “用印度語或者你喜歡的語言輸入”">​</a></h3><p>一旦你添加完所有語言後，你就會從你的 Ubuntu 桌面上的頂端菜單下載欄看到它們。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Choose-input-language-from-top-bar-in-Ubuntu.png" alt=""></p><p><em>從 Ubuntu 桌面的頂端欄選擇輸入語言。</em></p><p>你也可以使用鍵盤上的<strong>徽標鍵+空格鍵</strong>在不同語言中切換。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Choose-input-language-using-SuperSpace-keys.png" alt=""></p><p><em>在 Ubuntu 裏用<strong>徽標鍵+空格鍵</strong>選擇輸入語言</em></p><p>打開任何 GUI 文本編輯器/應用開始打字吧！</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Setup-Multilingual-Input-Method-On-Ubuntu.png" alt=""></p><p><em>在 Ubuntu 中用印度語輸入</em></p><h3 id="將-ibus-加入啓動應用" tabindex="-1">將 IBus 加入啓動應用 <a class="header-anchor" href="#將-ibus-加入啓動應用" aria-label="Permalink to “將 IBus 加入啓動應用”">​</a></h3><p>我們需要讓 IBus 在每次重啓後自動打開，這樣每次你想要用自己喜歡的語言輸入的時候就無須手動打開。</p><p>為此僅須在面板中輸入“開機應用”點開開機應用選項。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Launch-startup-applications-in-ubuntu.png" alt=""></p><p>在下個窗口，點擊添加，在名字欄輸入“Ibus”並在命令欄輸入“ibus-daemon”點擊添加按鈕。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Add-Ibus-to-startup-applications-on-Ubuntu.png" alt=""></p><p><em>在 Ubuntu 中將 Ibus 添加進開機啓動項</em></p><p>從現在起 IBus 將在系統啓動後自動開始。</p><p>現在到你的回合了。在什麼應用/工具中你用當地的印度語輸入？在下方評論區讓我們知道它們。</p><p>參考：</p>',62)),e("ul",null,[e("li",null,[u(p,{href:"https://help.ubuntu.com/community/ibus"},{default:s(()=>[...t[0]||(t[0]=[n("IBus – Ubuntu 社區百科",-1)])]),_:1})])]),t[17]||(t[17]=e("hr",null,null,-1)),e("p",null,[t[2]||(t[2]=n("via: ",-1)),u(p,{href:"https://www.ostechnix.com/how-to-setup-multilingual-input-method-on-ubuntu/"},{default:s(()=>[...t[1]||(t[1]=[n("https://www.ostechnix.com/how-to-setup-multilingual-input-method-on-ubuntu/",-1)])]),_:1})]),e("p",null,[t[7]||(t[7]=n("作者：",-1)),u(p,{href:"https://www.ostechnix.com/author/sk/"},{default:s(()=>[...t[3]||(t[3]=[n("sk",-1)])]),_:1}),t[8]||(t[8]=n(" 選題：",-1)),u(p,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[4]||(t[4]=[n("lujun9972",-1)])]),_:1}),t[9]||(t[9]=n(" 譯者：",-1)),u(p,{href:"https://github.com/tomjlw"},{default:s(()=>[...t[5]||(t[5]=[n("tomjlw",-1)])]),_:1}),t[10]||(t[10]=n(" 校對：",-1)),u(p,{href:"https://github.com/wxy"},{default:s(()=>[...t[6]||(t[6]=[n("wxy",-1)])]),_:1})]),e("p",null,[t[13]||(t[13]=n("本文由 ",-1)),u(p,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[11]||(t[11]=[n("LCTT",-1)])]),_:1}),t[14]||(t[14]=n(" 原創編譯，",-1)),u(p,{href:"https://linux.cn/"},{default:s(()=>[...t[12]||(t[12]=[n("Linux中國",-1)])]),_:1}),t[15]||(t[15]=n(" 榮譽推出",-1))])])}const I=o(g,[["render",m]]);export{f as __pageData,I as default};
